package tech.annexflow.lvm.storage

import androidx.datastore.core.CorruptionException
import androidx.datastore.core.okio.OkioSerializer
import kotlin.coroutines.cancellation.CancellationException
import okio.Buffer
import okio.BufferedSink
import okio.BufferedSource

/**
 * An [OkioSerializer] that stores a [T] with [read] and [write], for a format that kotlinx-serialization doesn't
 * cover, such as protos generated by Wire or a format of the app's own. [defaultValue] produces the value of a store
 * whose file doesn't exist yet.
 *
 * The whole file is read into memory before [read] runs, so a failure to read the file passes through as an
 * `IOException`. Any exception that [read] throws, other than a [CancellationException], fails with a
 * [CorruptionException] that holds it as its cause, and a store from [createDataStore] then starts over from
 * [defaultValue].
 *
 * A store of a message generated by Wire:
 *
 * ```kotlin
 * val preferences = createDataStore(
 *     appDirectories,
 *     "preferences.pb",
 *     okioSerializer(
 *         defaultValue = { UserPreferences() },
 *         read = { source -> UserPreferences.ADAPTER.decode(source) },
 *         write = { preferences, sink -> UserPreferences.ADAPTER.encode(sink, preferences) },
 *     ),
 * )
 * ```
 */
public fun <T> okioSerializer(
    defaultValue: () -> T,
    read: suspend (BufferedSource) -> T,
    write: suspend (T, BufferedSink) -> Unit,
): OkioSerializer<T> = LambdaOkioSerializer(defaultValue, read, write)

private class LambdaOkioSerializer<T>(
    private val produceDefaultValue: () -> T,
    private val read: suspend (BufferedSource) -> T,
    private val write: suspend (T, BufferedSink) -> Unit,
) : OkioSerializer<T> {

    override val defaultValue: T get() = produceDefaultValue()

    override suspend fun readFrom(source: BufferedSource): T {
        // Outside of the try, a failed read of the disk stays an IOException and the file is kept. Inside, read sees
        // only bytes in memory, so an IOException it throws, such as the EOFException of a truncated file, is about
        // the content.
        val content = Buffer().also { source.readAll(it) }
        return try {
            read(content)
        } catch (e: CancellationException) {
            throw e
        } catch (
            // Decoders report invalid content with many types: Wire throws an IOException for malformed bytes and an
            // IllegalStateException for a missing required field, and hand-written ones throw whatever their checks
            // throw. With the file in memory, any of them means the content can't be decoded.
            @Suppress("TooGenericExceptionCaught") e: Exception,
        ) {
            throw CorruptionException("The file doesn't hold a valid value: ${e.message}", e)
        }
    }

    override suspend fun writeTo(t: T, sink: BufferedSink) {
        write(t, sink)
    }
}
